import java.util.*;import vn.rtr.aeris.control01.*;import vn.rtr.aeris.betaintegrated01.*;import vn.rtr.aeris.beta01runtime.Values;
/** Actual sampler and Authority, scripted advancing clock. NOT retained actual rejected pair. */
public final class ClockBoundaryMock {
 static void ok(boolean b,String s){if(!b)throw new AssertionError(s);}static final String SRC="touch-00000000-0000-0000-0000-000000000000",PROV="ROOT_INJECTED_ANDROID_TOUCH";static final RunLifecycle.Context CTX=new RunLifecycle.Context("clockboundary","e","b","o","g","p");
 static final class C implements InputScheduler.Clock{long now=323122998861L;List<String>order=new ArrayList<>();public long elapsedNs(){order.add("ELAPSED");long x=now;now+=750;return x;}public long uptimeNs(){order.add("UPTIME");long x=now/1000000*1000000;now+=750;return x;}public long threadId(){return 2;}}
 static final class Q implements InputScheduler.Serial{Runnable task;public void execute(Runnable r){task=r;}public void later(Runnable r,long ms){}public void shutdown(){}}
 public static void main(String[]args)throws Exception{boolean candidate=args.length>0&&args[0].equals("candidate");C c=new C();Q q=new Q();List<ControlAuthority.Input>samples=new ArrayList<>();List<String>rejected=new ArrayList<>();ControlAuthority auth=new ControlAuthority(CTX,SRC,PROV,(k,m)->{});
  InputScheduler x=new InputScheduler(CTX,SRC,PROV,7,c,q,new InputScheduler.Sink(){public void input(ControlAuthority.Input i){samples.add(i);try{auth.accept(i,c.now);}catch(Exception e){rejected.add(e.getMessage());}}public void action(String a,String id,String h,long at){}public void invalid(String why){throw new AssertionError(why);}public void observation(Map<String,Object>m){}});
  x.publishUI(new InputScheduler.Snapshot(323122998000L,0,0,0,1,7,0,true,true,true,new double[4],0,-1));x.action("STATUS","a",null,323122998000L);q.task.run();ok(samples.size()==1,"onesample");ControlAuthority.Input i=samples.get(0);if(candidate){ok(i.uptimeNs<=i.elapsedNs&&rejected.isEmpty(),"neworderedpairaccepted");ok(c.order.equals(Arrays.asList("ELAPSED","UPTIME","ELAPSED")),"actualneworder");}else{ok(i.elapsedNs==323122999611L&&i.uptimeNs==323123000000L,"counterexamplepair");ok(rejected.equals(Arrays.asList("INPUT_CONTEXT_SEQUENCE_CLOCK_OR_AGE")),"actualauthorityrefusal");}
  System.out.println(Values.json(Values.map("status","PASS","variant",candidate?"uptime-first-candidate":"elapsed-first-baseline","elapsedNs",i.elapsedNs,"uptimeNs",i.uptimeNs,"clockCalls",c.order,"authorityRejected",rejected,"scope","ACTUAL_CORE_CLASSES_ADVANCING_SYNTHETIC_BOUNDARY_CLOCK_NOT_ACTUAL_REJECTED_PAIR")));
 }
}
